			        var dmParam = app.lookup("dmDefInfo");
			        dmParam.build(e.newValue);
			        
			        var rcp1 = dmParam.getValue("RCPT_RQST_COURS_LCLAS_SE_CD");
			        var rcp2 = dmParam.getValue("RCPT_RQST_COURS_MLSFC_SE_CD");
