			function onCalBrthYmdValueChange(e){
			    //연령계산
			    var date = new Date();
			    var val1 = date.getFullYear();
			    var val2 = app.lookup("calBrthYmd").value.substr(0,4);
			    var age  = Number(val1)-Number(val2);
			    
			    if(val2.length == 0) age = 0;
			    app.lookup("ipb16").value = "(만 "+age+"세)";
			    
			    if(age < 19){
			        util.Control.setReadOnly(app, false, ["grp7"]);
			    } else {
			        util.Control.setReadOnly(app, true, ["grp7"]);
			    }
			}

